INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defender of the Crown', 'The Age of Chivalry! A time of lusty wenches and black hearted villains. King Richard has been murdered and England is thrown into civil war! Amidst the ringing clash of steel and the thunder of charging steeds the bold Saxon knights have chosen you to lead them into battle against the hated Normans. Victory will not come easy. To save England your skills as swordsman and military leader will be severely tested. But should you succeed you’ll win the Crown of England and the love of many a beautiful damsel!' FROM games WHERE igdb_id = 1873 ON CONFLICT (game_id, language_code) DO NOTHING;
