INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Salamander', 'Salamander is a scrolling shooter arcade game released by Konami as a spin-off to Gradius. It introduced a simplified power-up system, two-player cooperative gameplay and both horizontally and vertically scrolling stages. Some of these would later become the norm for future Gradius games.' FROM games WHERE igdb_id = 1477 ON CONFLICT (game_id, language_code) DO NOTHING;
