INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda', 'The Legend of Zelda is the first title in the Zelda series, it has marked the history of video games particularly for it''s game mechanics and universe. The player controls Link and must make his way through the forests, graveyards, plains and deserts of the Otherworld to find the secret entrances to the eight dungeons and try to restore the broken Triforce. Among the game''s mechanics, it was the first time we saw a continuous world that could be freely explored, power-ups that permanently enhanced the main character''s abilities and a battery save feature that allowed players to keep their progress instead of having to start over. The gameplay balanced action sequences with discovery, secrets and exploration.' FROM games WHERE igdb_id = 1022 ON CONFLICT (game_id, language_code) DO NOTHING;
