INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '720 Degrees', '720 Degrees is a 1986 arcade game by Atari Games. 720°, a skateboarding game, is notable in that along with BMX Simulator, it is one of the first extreme sports video games, and has a unique timed structure that requires the player score points in order to keep the game going.' FROM games WHERE igdb_id = 8580 ON CONFLICT (game_id, language_code) DO NOTHING;
