INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kikstart II', 'Kikstart 2 is a motorcycle trials racing videogame released for the Amiga, Amstrad CPC, Commodore 64 and ZX Spectrum. It enjoyed more success than its predecessor, Kikstart. The game allowed 2-player simultaneous (via a split-screen facility) or 1-player, vs-computer play. The game mechanics were copied into other games too, like the Game Boy game "Motocross Maniacs".
