INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth: The Computer Game', 'Labyrinth: The Computer Game is a 1986 graphic adventure game developed by Lucasfilm Games and published by Activision. Based on the fantasy film Labyrinth, it tasks the player with navigating a maze while solving puzzles and evading dangers. The player''s goal is to find and defeat the main antagonist, Jareth, within 13 real-time hours. Unlike other adventure games of the period, Labyrinth does not feature a command-line interface. Instead, the player uses two scrolling "word wheel" menus on the screen to construct basic sentences.' FROM games WHERE igdb_id = 7517 ON CONFLICT (game_id, language_code) DO NOTHING;
