INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Side Pocket', 'Side Pocket is a pocket billiards video game originally released into arcades by Data East in 1986. The arcade version was eventually ported to six home console platforms and two sequels to the game were produced, as well as a spin-off series called Pocket Gal. G-Mode currently owns the intellectual property rights to the Side Pocket series, and licenses these games globally.' FROM games WHERE igdb_id = 6048 ON CONFLICT (game_id, language_code) DO NOTHING;
