INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest III: To Heir is Human', 'King''s Quest III: To Heir is Human is an adventure game in the King''s Quest series. Players control Gwydion, a young slave to the evil wizard Manannan in the land of Llewdor. The game follows Gwydion''s journey as he learns magic, escapes his captor, and discovers his true identity as the lost prince of Daventry. Players must solve puzzles, avoid the wizard''s watchful eye, and navigate various dangers to complete their quest. The game expands on the series'' fantasy setting, introducing new locations and characters while maintaining the puzzle-solving and exploration elements that define the King''s Quest franchise. As the third installment in the series, King''s Quest III continues the story of the royal family of Daventry, connecting to the broader narrative of the King''s Quest saga.' FROM games WHERE igdb_id = 893 ON CONFLICT (game_id, language_code) DO NOTHING;
