INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball', 'Dragon Ball (also known as Dragon Ball: Le Secrets du Dragon and Dragon Ball: Shenron no Nazo) is the second video game based on the Dragon Ball series (its predecessor being Dragon Ball: Dragon Daihikyou) and the first Dragon Ball game produced and distributed by Bandai. It is an action game developed by TOSE Software Company. It was released for the Family Computer on November 27, 1986 in Japan. Outside Japan, a graphically altered version released for the North American market in March 1988 under the title of Dragon Power, which divorced the game from the Dragon Ball licensing. A European version which retained the license, simply titled Dragon Ball, was also released in 1990 primarily for the French market.
