INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hudson''s Adventure Island', 'Hudson''s Adventure Island, also known simply as Adventure Island and released in Japan as Takahashi Meijin no Bouken-jima, is a side-scrolling platform game produced by Hudson Soft that was first released in Japan for the Famicom and MSX on September 12, 1986. It was later released in North America for the Nintendo Entertainment System on September 1988 and in the PAL region in 1992 under the title of Adventure Island Classic.
