INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trojan', 'The arcade version can be played by up to two players alternating. The game''s controls consists of an eight-way joystick and two action buttons. Similarly to Kung-Fu Master or Rush''n Attack, the player jumps by holding the joystick upwards instead of having a dedicated jump button like other side-scrolling action games. Instead, one button is used to swing the sword at enemies and the other button is used to hold the shield to block enemy attacks, including projectiles such as throwing knives and arrows. The shield can be held towards the player while standing or crouching, as well as upwards vertically and diagonally. Some enemies will throw magic balls which will cause the player to lose their sword and shield if they block. During these instances, the player will fight barehanded, with the sword and shield buttons used to punch and kick respectively. The sword and shield will appear on-screen after some point, allowing the player to recover their weapon. Other power-ups includes floating hearts that will restore the player''s health and jumping spots where the player can jump higher than usual.
