INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mappy-Land', 'Mappy, who is a policeman, prepared all kinds of wonderful birthday presents for his girlfriend, Mapico. But, Nyamco and his child Mukies have hidden them in the eight towns of Mappyland. What a pity! Mappy must hurry to get the presents back before Mapico''s birthday party. The problem is that there are so many mysterious towns where Mappy must search, while fighting off his enemies. Can you accept the challenge and help Mappy to succeed?' FROM games WHERE igdb_id = 48179 ON CONFLICT (game_id, language_code) DO NOTHING;
