INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman', 'Batman is a 1986 3D isometric action-adventure game by Ocean Software for the Amstrad PCW, Amstrad CPC, ZX Spectrum, and MSX and MSX2 microcomputers, and the first Batman game ever developed. Upon release, the game received favorable reviews, and received a sequel two years later, titled Batman: The Caped Crusader.' FROM games WHERE igdb_id = 26457 ON CONFLICT (game_id, language_code) DO NOTHING;
