INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombi', 'Zombi is an icon-driven action-adventure video game and Ubisoft''s first publication. It is a first-person action adventure with four protagonists exploring a zombie-filled shopping mall. If a character''s health is depleted, he turns into a zombie, which then roams the room they died in. Zombies can be killed either by numerous body shots, or a single shot to the head. Characters are named after the creators of the game.' FROM games WHERE igdb_id = 2279 ON CONFLICT (game_id, language_code) DO NOTHING;
