INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Dribble', 'Double Dribble was the second basketball arcade game developed and released in 1986 by Konami, following Super Basketball. Much of the game''s popularity came from its animation sequences showing basketball players performing slam dunks, as well as The Star-Spangled Banner theme during attract mode, which was the first arcade game to feature the national anthem. These were uncommon in video games at the time of Double Dribble''s release. While successful in the arcades, the game became and remained popular and remembered when it was ported to the Nintendo Entertainment System in 1987.' FROM games WHERE igdb_id = 4699 ON CONFLICT (game_id, language_code) DO NOTHING;
