INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quartet', 'A platform shoot-em-up hybrid from Sega for one to four players, selected from either Joe (yellow), Mary (red), Lee (blue) and Edgar (green). The action takes place over a number of sideways scrolling levels, the bulk of which consist of straightforward platform action. On some levels, however, there are jet packs for the players to collect, and the gameplay''s emphasis switched to that of a standard, sideways scrolling shoot-em-up.
