INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arkanoid', 'Arkanoid is an arcade game developed by Taito in 1986. It expanded upon Atari''s Breakout games of the 1970s by adding power-ups, different types of bricks, and a variety of level layouts. The title refers to a doomed "mothership" from which the player''s ship, the Vaus, escapes.' FROM games WHERE igdb_id = 4595 ON CONFLICT (game_id, language_code) DO NOTHING;
