INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Milon''s Secret Castle', 'Guide Milon through the four levels of Garland Castle in his quest to reach the top floor and vanquish the big boss! The journey is a difficult one though, because the castle is locked up tight and Milon doesn''t have the keys. You will have to use your bubble attacks to fend off the castle baddies while busting up every block in sight trying to find all of the hidden treasure and other secrets throughout the game. Unlike most platformers, Milon''s Secret Castle is less about defeating all of the enemies in an area, and more about scouring every bit of each room to find the secrets that lie within Garland Castle! Milo can uncover practically anything in the game. This includes: items, power-ups, money, shields, keys, level exits, even shops! The only way to get to each level boss is to find the right secret items!' FROM games WHERE igdb_id = 48081 ON CONFLICT (game_id, language_code) DO NOTHING;
