INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Towers', 'On the moonlit eve of his coronation ceremony, pensive Prince Myer sits at the lakeside to ponder the future of the kingdom. Suddenly, a shadowy kami called Khan rises from the lake and coalesces into the form of a man. Although he doesn''t identify himself, the figure greets Prince Myer by name, and informs him that the wizard Rubas, the "Devil of Darkness", is preparing to overtake Willner Kingdom by using seven magic bells capable of' FROM games WHERE igdb_id = 48067 ON CONFLICT (game_id, language_code) DO NOTHING;
