INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rygar', 'An evil being known as Ligar is about to conquer the land of Argool. Such is his power that no living creature dares to cross paths with him. But the legendary warrior Rygar rises from his grave to restore peace and justice. Armed with his famed weapon Diskarmor, Rygar begins to traverse the vast lands that lead to the lair of the demon, as his minions are trying in vain to stop him...' FROM games WHERE igdb_id = 6856 ON CONFLICT (game_id, language_code) DO NOTHING;
