INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace of Aces', 'Ace of Aces is a combat flight simulator developed by Artech Digital Entertainment in 1986. The game takes place during World War II and the player flies a RAF Mosquito long range fighter-bomber equipped with rockets, bombs and a cannon. Missions include destroying German fighter planes, bombers, V-1 flying bombs, U-boats, and trains.' FROM games WHERE igdb_id = 11863 ON CONFLICT (game_id, language_code) DO NOTHING;
