INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albatross', 'Albatross offers a captivating golf experience from a top-down perspective, featuring a challenging 18-hole course. Players can customize their play by choosing from 14 different clubs, including drivers, irons, and a putter. Fine-tune your game with options to adjust your stance, control how you strike the ball, and perfect your swing. The game uniquely presents a split-screen layout, providing both an overhead view of the entire hole and a close-up look at your ball''s position. A status bar includes all the essential information you need during play. Enjoy various gameplay modes such as single-player stroke play, multiplayer stroke play, or multiplayer match play.' FROM games WHERE igdb_id = 86147 ON CONFLICT (game_id, language_code) DO NOTHING;
