INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Might and Magic: Book One - The Secret of the Inner Sanctum', 'Feel the power... Experience the magic! Lead your party of hand-picked adventurers into the enchanted Land of Varn. From dark, moldy caverns through corridors of majestic castles, you''ll travel in search of clues to unlock the Secret of the Inner Sanctum. Daring exploits of heroism and sorcery will keep you riveted for hours. Choose from a variety of extraordinary personalities and lead them on an adventure of a lifetime. Over 250 weapons and items and more than 92 mystical spells to use in your search for the Inner Sanctum. Battle legions of ravenous monsters as you travel through forests and islands shrouded in mystery.' FROM games WHERE igdb_id = 7733 ON CONFLICT (game_id, language_code) DO NOTHING;
