INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Sprint', 'Super Sprint is a racing video game released by Atari Games and Midway Games in 1986. Up to three players drive Formula One-like cars on a circuit that is viewed from above. The game is a successor to Gran Trak 10 and the Sprint series, which were black-and-white games from the 1970s. A sequel, Championship Sprint, was released later in the same year.' FROM games WHERE igdb_id = 28385 ON CONFLICT (game_id, language_code) DO NOTHING;
