INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solaris', 'Solaris is a space combat game for the Atari 2600 published in 1986 by Atari Corporation. It was developed by Doug Neubauer, who owns the copyright and the Solaris trademark. The game is a sequel to Neubauer''s Atari 8-bit family game Star Raiders from 1979. Both games feature an enemy race known as Zylons, but Star Raiders uses a first-person perspective while Solaris is in third-person.
