INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gauntlet II', 'The gameplay is very similar to the original Gauntlet, a topdown dungeon crawl supporting up to four players. The biggest difference from the original game is that players can choose identical classes, instead of being limited to a particular one for each joystick; each player is differentiated by color. Thus, instead of having a "warrior", "wizard", and "valkyrie" (for instance), in Gauntlet II there could be a "red wizard", a "blue elf" and a "green warrior".
