INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire Killer', 'Vampire Killer is a side-view flick-screen game where you are a Vampire hunter who has been tasked to remove Dracula from the 12th floor of a block of flats by a client on the floor below. The problem is, as well as facing and killing a vampire, the job has to be completed before midnight which is only eight minutes away. In your rush to get to the building you have forgotten your equipment like garlic and stakes, which is needed to face Dracula. You have to get to the 12th floor using elevators (which have minds of their own and can take you down as well as up), and you must look behind the doors of each flat for equipment to help you.
