INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Erika', 'Near future. The unknown black shadow enemy is planning to conquer the Earth. Erika is a special agent on a mission to investigate enemy''s new weapon Spectron. Protagonist is an information agent that gets into contact with Erika to receive information from her. Together they must infiltrate enemy base and destroy the secret weapon.' FROM games WHERE igdb_id = 91464 ON CONFLICT (game_id, language_code) DO NOTHING;
