INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solomon''s Key', 'Solomon''s Key is a puzzle game developed by Tecmo in 1986 for arcade release on custom hardware based on the Z80 chipset. The game is generally recognized as one of the most difficult games to appear on the NES. The player, controlling a sorcerer known only as Dana must overcome unlimited enemy spawning, challenging level designs, a countdown timer, instant death from any physical contact with enemies, and limited ways to dispatch enemies.' FROM games WHERE igdb_id = 28384 ON CONFLICT (game_id, language_code) DO NOTHING;
