INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athena', 'Athena is a platformer arcade game, also released on a number of consoles. It was developed by SNK for the arcade, and was ported to the NES by Micronics, and a number of other platforms by Ocean Software. The game featured a female protagonist, although explicitly utilizing the female body as a selling-feature for the game.' FROM games WHERE igdb_id = 9052 ON CONFLICT (game_id, language_code) DO NOTHING;
