INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros.: The Lost Levels', 'Super Mario Bros.: The Lost Levels is a direct sequel to Super Mario Bros. Not to be confused with the western Super Mario Bros. 2, this sequel to Super Mario Bros. is very much an expansion to the original, with many reused graphics and concepts, though new ones are also present. The game was initially released for the Japan-only Family Computer Disk System.' FROM games WHERE igdb_id = 1066 ON CONFLICT (game_id, language_code) DO NOTHING;
