INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alter-ego', 2303, '1986-04-27', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ynj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/up7eatq179me1ifqkgt4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alter Ego', 'Alter Ego is a life simulation game where players create a character and guide them through seven life phases from infancy to old age by making decisions in various situations. Players choose from multiple response options that influence personality, health, and future scenarios, with each choice carrying long-term consequences that can lead to different outcomes including early death or game over. The gameplay unfolds through a life tree structure with situation cards representing thematic encounters, and players can manage relationships, careers, and lifestyle choices as their character ages, with separate male and female versions available.' FROM games WHERE igdb_id = 2303 ON CONFLICT (game_id, language_code) DO NOTHING;
