INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starflight', 'Starflight is a space exploration role-playing adventure video game developed by Binary Systems and published by Electronic Arts in 1986. Originally developed for IBM compatible and Tandy systems, it was later released for the Amiga, Atari ST, Macintosh and Commodore 64. A fully revamped version of the game was developed for the Sega Mega Drive/Genesis in 1991.
